<script setup>
import {computed,onMounted,onUnmounted,ref} from "vue";import {useRouter} from "vue-router";
import {NButton,NEmpty,NTag,NAlert,useMessage} from "naive-ui";
import PageShell from "../components/PageShell.vue";import Panel from "../components/Panel.vue";
import {approvalsApi} from "../api.js";import {openSession} from "../navigation.js";import {can} from "../access.js";import {dateText} from "../display.js";
const router=useRouter(),message=useMessage(),items=ref([]),loading=ref(false),error=ref(""),busy=ref(""),lastUpdated=ref(null);let timer;
async function load(quiet=false){if(!quiet)loading.value=true;try{items.value=await approvalsApi.list();lastUpdated.value=Date.now();error.value="";}catch(e){error.value=`刷新失败：${e.message}，当前展示上次结果`;}finally{loading.value=false;}}
async function decide(item,approved){busy.value=item.requestId;try{await approvalsApi.decide(item.sessionId,item.requestId,approved);items.value=items.value.filter(v=>v.requestId!==item.requestId||v.sessionId!==item.sessionId);message.success(approved?'已批准，任务继续执行':'已拒绝本次操作');}catch(e){if(e.status===409){message.warning('审批已被其他人处理');await load(true);}else message.error(e.message);}finally{busy.value="";}}
function title(item){return item.args?.applicant?`${item.args.applicant}的${item.args.type||'申请'}`:`执行${item.toolName||'业务操作'}`;}
const fields={applicant:'申请人',type:'类型',amount:'金额',reason:'事由'};
async function visit(item){try{await openSession(router,item.sessionId);}catch(e){message.error(e.message);}}
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden)load(true);},10000);});onUnmounted(()=>clearInterval(timer));
</script><template><PageShell title="审批" subtitle="核实操作目标与参数，再决定是否允许继续执行" :loading="loading" :error="error"><template #actions><n-button @click="load()">刷新</n-button></template><n-alert type="warning" :bordered="false" style="margin-bottom:20px">待办只存在内存中，服务重启后会消失。本页不保存审批历史，操作记录请查阅审计。</n-alert><div class="toolbar"><b>待处理 {{items.length}} 条</b><span class="secondary">每 10 秒刷新 · 最近更新 {{dateText(lastUpdated)}}</span></div><n-empty v-if="!items.length&&!loading" description="没有待处理的审批" class="empty-state"/><Panel v-for="item in items" :key="item.sessionId+item.requestId" :title="title(item)" style="margin-bottom:16px"><template #actions><n-tag :type="item.risk==='high'?'error':'warning'">{{item.risk==='high'?'高风险':'需要确认'}}</n-tag></template><dl v-if="item.args?.applicant" class="detail-grid"><template v-for="(label,key) in fields" :key="key"><dt>{{label}}</dt><dd>{{key==='amount'?'¥ '+Number(item.args[key]??0).toLocaleString('zh-CN'):item.args[key]||'—'}}</dd></template></dl><p class="hint">发起时间 {{dateText(item.askedAt)}} · {{item.sessionTitle||item.workflowName||'业务会话'}}</p><details><summary>完整操作参数</summary><p class="hint">{{item.toolName}}</p><pre class="json-view">{{JSON.stringify(item.args,null,2)}}</pre></details><div class="action-row" style="margin-top:20px"><n-button @click="visit(item)">查看原会话</n-button><span style="flex:1"/><n-button v-if="can('session.run')" :loading="busy===item.requestId" @click="decide(item,false)">拒绝</n-button><n-button v-if="can('session.run')" type="primary" :loading="busy===item.requestId" @click="decide(item,true)">批准并继续</n-button></div></Panel></PageShell></template>
